    };
  }

  return _typeof();
}
```

### Expected behaviour

```js
export default function _typeof_1() {
    if (Date_2.now_0() > 0) {
        _typeof_1 = function _typeof_3() {
            console_2.log_0(0);
        };
    } else {
        _typeof_1 = function _typeof_4() {
            console_2.log_0(2);
        };
    }
    return _typeof_1();
};
```

### Actual behaviour

```js
export default function _typeof_1(obj_2) {
    if (obj_2 != null) {
        __typeof_0 = function _typeof_3(obj_3) { // <-- left hand side should be _typeof_1
            console_4.log_0(0);
        };
    } else {
        __typeof_0 = function _typeof_5(obj_5) { // <-- left hand side should be _typeof_1
            console_4.log_0(2);
        };
    }
    return __typeof_0(obj_2);
};
```

### Reproduction

```rust
use swc::{self, config::Options};
use swc_atoms::JsWord;
use swc_common::{
    chain, comments::SingleThreadedComments, sync::Lrc, FileName, Globals, Mark, SourceMap,
    SyntaxContext, DUMMY_SP,
};
use swc_ecma_ast::{
    Decl, DefaultDecl, ExportDefaultDecl, Ident, ImportSpecifier, Invalid, Module, ModuleDecl,
    ModuleItem,
};
use swc_ecma_codegen::{text_writer::JsWriter, Config, Emitter};
use swc_ecma_parser::{lexer::Lexer, EsConfig, PResult, Parser, StringInput, Syntax, TsConfig};
use swc_ecma_preset_env::{preset_env, BrowserData, Mode, Targets, Version};
use swc_ecma_transforms::{
    compat::reserved_words::reserved_words,
    fixer,
    fixer::paren_remover,
    helpers, hygiene,
    optimization::simplify::{dead_branch_remover, expr_simplifier},
    react, resolver,
};
use swc_ecma_transforms_compat::es2015;
use swc_ecma_visit::{Fold, FoldWith};

fn main() {
    let cm = Lrc::<SourceMap>::default();
    let src = r#"
    export default function _typeof() {
        if (Date.now() > 0) {
          _typeof = function _typeof() {
            console.log(0);
          };
        } else {
          _typeof = function _typeof() {
            console.log(2);
          };
        }
      
        return _typeof();
      }
"#;
    let (module, comments) = parse(src, "test.js", &cm).unwrap();

    swc_common::GLOBALS.set(&Globals::new(), || {
        helpers::HELPERS.set(&helpers::Helpers::default(), || {
            let unresolved_mark = Mark::fresh(Mark::root());
            let global_mark = Mark::fresh(Mark::root());
            let module = module.fold_with(&mut resolver(unresolved_mark, global_mark, false));

            let module = module.fold_with(&mut preset_env(
                global_mark,
                Some(&comments),
                swc_ecma_preset_env::Config {
                    targets: Some(Targets::Versions(BrowserData {
                        safari: Some(Version {
                            major: 15,
                            minor: 1,
                            patch: 0,
                        }),
                        ..Default::default()
                    })),
                    bugfixes: true,
                    ..Default::default()
                },
                Default::default(),
            ));

            let module = module.fold_with(&mut Test {});

            let module = module.fold_with(&mut chain!(
                reserved_words(),
                hygiene(),
                fixer(Some(&comments))
            ));

            let code = emit(&module, &comments, cm);
            println!("{}", code);
        });
    });
}

struct Test {
}
impl Fold for Test {
    fn fold_ident(&mut self, node: Ident) -> Ident {
        let new_name: JsWord = format!("{}_{}", node.sym, node.span.ctxt().as_u32()).into();
        Ident::new(new_name, node.span)
    }
}

fn parse(
    code: &str,
    filename: &str,
    cm: &Lrc<SourceMap>,
) -> PResult<(Module, SingleThreadedComments)> {
    let source_file = cm.new_source_file(FileName::Real(filename.into()), code.into());
    let comments = SingleThreadedComments::default();

    let lexer = Lexer::new(
        Syntax::Es(EsConfig {
            jsx: true,
            ..Default::default()
        }),
        Default::default(),
        StringInput::from(&*source_file),
        Some(&comments),
    );
    let mut parser = Parser::new_from(lexer);
    match parser.parse_module() {
        Err(err) => Err(err),
        Ok(module) => Ok((module, comments)),
    }
}

fn emit(module: &Module, comments: &SingleThreadedComments, cm: Lrc<SourceMap>) -> String {
    let mut buf = vec![];
    {
        let writer = Box::new(JsWriter::new(cm.clone(), "\n", &mut buf, None));
        let config = Config { minify: false };
        let mut emitter = Emitter {
            cfg: config,
            comments: Some(&comments),
            cm,
            wr: writer,
        };
        emitter.emit_module(&module).unwrap();
    }

    String::from_utf8(buf).unwrap()
}
```

