 *
 * Nestjs swagger does not support a oneOf at the top level of a model. As such we create an OpenAPI definition manually
 */

type SchemaObject = OpenAPIObject['components']['schemas']['key']

export class PersonGet {}

export const personSchemaObject: SchemaObject = {
  oneOf: [
    {
      $ref: getSchemaPath(CompanyGet),
    },
    {
      $ref: getSchemaPath(UserGet),
    },
  ],
  discriminator: {
    propertyName: '_resolveType',
    mapping: {
